// pls - a prettier ls replacement
use std::path::{Path, PathBuf};
use std::fs;
use clap::Parser;

mod icons;
mod node;
mod display;
mod detail;

use node::Node;
use display::Display;
use detail::DetailField;

#[derive(Parser, Debug)]
#[command(
    name = "pls",
    about = "pls is a prettier and powerful ls(1) for the pros.\n\nRead docs: https://pls.cli.rs/\nGet source: https://github.com/pls-rs/pls/\nSponsor: https://github.com/sponsors/dhruvkb/",
    version = "0.0.1-beta.9",
    long_about = None,
)]
struct Args {
    /// the paths to list, each of which may be a file or directory
    #[arg(value_name = "PATHS", default_value = ".")]
    paths: Vec<PathBuf>,

    // Detail view options
    /// the data points to show about each node
    #[arg(short = 'd', long = "det", value_name = "DETAILS",
          default_value = "none",
          value_parser = parse_detail,
          help_heading = "Detail view")]
    det: Vec<DetailField>,

    /// show headers above columnar data
    #[arg(short = 'H', long = "header", value_name = "HEADER",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Detail view")]
    header: bool,

    /// the type of units to use for the node sizes
    #[arg(short = 'u', long = "unit", value_name = "UNIT",
          default_value = "binary",
          value_parser = ["binary", "decimal", "none"],
          help_heading = "Detail view")]
    unit: String,

    // Grid view options
    /// display node names in multiple columns
    #[arg(short = 'g', long = "grid", value_name = "GRID",
          default_value = "false",
          value_parser = parse_bool,
          help_heading = "Grid view")]
    grid: bool,

    /// display node names column-first
    #[arg(short = 'D', long = "down", value_name = "DOWN",
          default_value = "false",
          value_parser = parse_bool,
          help_heading = "Grid view")]
    down: bool,

    // Presentation options
    /// display icons next to node names
    #[arg(short = 'i', long = "icon", value_name = "ICON",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Presentation")]
    icon: bool,

    /// display node type suffixes after the node name
    #[arg(short = 'S', long = "suffix", value_name = "SUFFIX",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Presentation")]
    suffix: bool,

    /// show symlink targets
    #[arg(short = 'l', long = "sym", value_name = "SYM",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Presentation")]
    sym: bool,

    /// show dependent nodes as children of their principal nodes
    #[arg(short = 'c', long = "collapse", value_name = "COLLAPSE",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Presentation")]
    collapse: bool,

    /// align items accounting for leading dots
    #[arg(short = 'a', long = "align", value_name = "ALIGN",
          default_value = "true",
          value_parser = parse_bool,
          help_heading = "Presentation")]
    align: bool,

    // Filtering options
    /// the set of node types to include in the output
    #[arg(short = 't', long = "typ", value_name = "TYPES",
          default_value = "all",
          value_parser = parse_type,
          help_heading = "Filtering")]
    typ: Vec<NodeType>,

    /// the importance cutoff to dim or hide unimportant files
    #[arg(short = 'I', long = "imp", value_name = "IMP",
          default_value = "0",
          allow_hyphen_values = true,
          help_heading = "Filtering")]
    imp: i32,

    /// the pattern of files to selectively hide from the output
    #[arg(short = 'e', long = "exclude", value_name = "EXCLUDE",
          value_parser = parse_regex,
          help_heading = "Filtering")]
    exclude: Option<regex::Regex>,

    /// the pattern of files to exclusively show in the output
    #[arg(short = 'o', long = "only", value_name = "ONLY",
          value_parser = parse_regex,
          help_heading = "Filtering")]
    only: Option<regex::Regex>,

    // Sorting options
    /// the set of fields to sort by, trailing `_` reverses the direction
    #[arg(short = 's', long = "sort", value_name = "SORT_BASES",
          default_value = "cat",
          value_parser = parse_sort,
          help_heading = "Sorting")]
    sort: Vec<SortField>,
}

fn parse_bool(s: &str) -> Result<bool, String> {
    match s {
        "true" => Ok(true),
        "false" => Ok(false),
        v => Err(format!("invalid boolean value: {}", v)),
    }
}

fn parse_detail(s: &str) -> Result<DetailField, String> {
    DetailField::from_str(s).ok_or_else(|| format!("invalid detail field: {}", s))
}

fn parse_type(s: &str) -> Result<NodeType, String> {
    NodeType::from_str(s).ok_or_else(|| format!("invalid type: {}", s))
}

fn parse_sort(s: &str) -> Result<SortField, String> {
    SortField::from_str(s).ok_or_else(|| format!("invalid sort field: {}", s))
}

fn parse_regex(s: &str) -> Result<regex::Regex, String> {
    regex::Regex::new(s).map_err(|e| e.to_string())
}

#[derive(Debug, Clone, PartialEq)]
pub enum NodeType {
    Dir,
    Symlink,
    Fifo,
    Socket,
    BlockDevice,
    CharDevice,
    File,
    None_,
    All,
}

impl NodeType {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "dir" => Some(NodeType::Dir),
            "symlink" => Some(NodeType::Symlink),
            "fifo" => Some(NodeType::Fifo),
            "socket" => Some(NodeType::Socket),
            "block-device" => Some(NodeType::BlockDevice),
            "char-device" => Some(NodeType::CharDevice),
            "file" => Some(NodeType::File),
            "none" => Some(NodeType::None_),
            "all" => Some(NodeType::All),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub enum SortField {
    Dev, Ino, Nlink, Typ, Cat, User, Uid, Group, Gid, Size, Blocks,
    Btime, Ctime, Mtime, Atime, Name, Cname, Ext, None_,
    // Reversed versions
    InodeR, NlinksR, TypR, CatR, UserR, UidR, GroupR, GidR, SizeR,
    BlocksR, BtimeR, CtimeR, MtimeR, AtimeR, NameR, CnameR, ExtR,
}

impl SortField {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "dev" => Some(SortField::Dev),
            "ino" => Some(SortField::Ino),
            "nlink" => Some(SortField::Nlink),
            "typ" => Some(SortField::Typ),
            "cat" => Some(SortField::Cat),
            "user" => Some(SortField::User),
            "uid" => Some(SortField::Uid),
            "group" => Some(SortField::Group),
            "gid" => Some(SortField::Gid),
            "size" => Some(SortField::Size),
            "blocks" => Some(SortField::Blocks),
            "btime" => Some(SortField::Btime),
            "ctime" => Some(SortField::Ctime),
            "mtime" => Some(SortField::Mtime),
            "atime" => Some(SortField::Atime),
            "name" => Some(SortField::Name),
            "cname" => Some(SortField::Cname),
            "ext" => Some(SortField::Ext),
            "none" => Some(SortField::None_),
            "inode_" => Some(SortField::InodeR),
            "nlinks_" => Some(SortField::NlinksR),
            "typ_" => Some(SortField::TypR),
            "cat_" => Some(SortField::CatR),
            "user_" => Some(SortField::UserR),
            "uid_" => Some(SortField::UidR),
            "group_" => Some(SortField::GroupR),
            "gid_" => Some(SortField::GidR),
            "size_" => Some(SortField::SizeR),
            "blocks_" => Some(SortField::BlocksR),
            "btime_" => Some(SortField::BtimeR),
            "ctime_" => Some(SortField::CtimeR),
            "mtime_" => Some(SortField::MtimeR),
            "atime_" => Some(SortField::AtimeR),
            "name_" => Some(SortField::NameR),
            "cname_" => Some(SortField::CnameR),
            "ext_" => Some(SortField::ExtR),
            _ => None,
        }
    }
}

fn main() {
    let args = Args::parse();
    println!("{:?}", args);
}
