    let type_filters = if args.typ.iter().any(|t| matches!(t, NodeTypeFilter::All)) {
        vec![NodeTypeFilter::All]
    } else if args.typ.iter().any(|t| matches!(t, NodeTypeFilter::None_)) {
        vec![NodeTypeFilter::None_]
    } else {
        args.typ.clone()
    };

