        detail_fields,
        show_header: args.header,
        unit: args.unit.clone(),
        grid: args.grid,
        down: args.down,
        show_icons: args.icon,
        show_suffix: args.suffix,
        show_sym: args.sym,
        collapse: args.collapse,
        align: args.align,
        type_filters,
        imp_cutoff: args.imp,
        exclude: args.exclude.clone(),
        only: args.only.clone(),
        sort_fields: args.sort.clone(),
        use_color,
        term_width,
    };

    let multiple = args.paths.len() > 1;
    let mut first = true;

    for path in &args.paths {
        if multiple {
            if !first { println!(); }
            first = false;
            if let Ok(abs) = path.canonicalize() {
                println!("\n{}:", abs.display());
            } else {
                println!("\n{}:", path.display());
            }
        }

        match display::list_path(path, &opts) {
            Ok(()) => {},
            Err(e) => {
                eprintln!("{}:\n\t{}", path.display(), e);
            }
        }
    }
}
