// Icon mapping for pls
// Uses Nerd Fonts (Material Design Icons + Devicons)

/// Returns the icon for a given filename and its type
pub fn get_icon(name: &str, is_dir: bool, is_symlink: bool) -> Option<char> {
    if is_symlink {
        return Some('\u{F0339}'); // nf-md-link  
    }

    if is_dir {
        return get_dir_icon(name);
    }

    get_file_icon(name)
}

fn get_dir_icon(name: &str) -> Option<char> {
    match name {
        ".git" => Some('\u{F02A2}'),     // nf-md-git
        ".github" => Some('\u{F408}'),   // nf-dev-github_badge
        "src" => Some('\u{F40D}'),       // nf-dev-rust (source directory)
        _ => Some('\u{F07B}'),           // nf-fa-folder generic
    }
}

fn get_file_icon(name: &str) -> Option<char> {
    // Exact filename matches first
    match name {
        ".env" => return Some('\u{E22F}'),         // nf-dev-aptana
        ".gitignore" | ".gitattributes" | ".gitmodules" => return Some('\u{F02A2}'), // nf-md-git
        "Cargo.toml" => return Some('\u{F487}'),   // nf-dev-rust
        "Cargo.lock" => return Some('\u{F456}'),   // nf-dev-lock
        "Dockerfile" | "docker-compose.yml" | "docker-compose.yaml" => return Some('\u{F4B7}'), // nf-dev-docker
        "LICENSE" | "LICENCE" => return Some('\u{F495}'),  // nf-dev-license
        "Makefile" | "GNUmakefile" | "makefile" => return Some('\u{F070E}'), // nf-md-cogs
        "README.md" | "readme.md" | "README" | "readme" => return Some('\u{F02D}'), // nf-fa-book_open
        "package.json" | "package-lock.json" => return Some('\u{E60B}'), // nf-dev-nodejs_small
        "pyproject.toml" => return Some('\u{E60B}'), // python project
        "requirements.txt" => return Some('\u{E612}'), // nf-dev-terminal
        _ => {}
    }

    // Extension matches
    let ext = get_extension(name);
    match ext {
        "rs" => Some('\u{E68B}'),       // nf-dev-rust
        "sh" | "bash" | "zsh" | "fish" => Some('\u{F489}'), // nf-dev-terminal
        "md" | "markdown" => Some('\u{F48A}'),  // nf-dev-markdown
        "txt" => Some('\u{E612}'),       // nf-dev-terminal (text)
        "json" => Some('\u{E60B}'),      // nf-dev-nodejs_small
        "toml" => Some('\u{E60B}'),      // config files
        "yaml" | "yml" => Some('\u{E60B}'), // config files
        "ini" | "cfg" | "conf" => Some('\u{E615}'), // nf-dev-aptana
        "png" | "jpg" | "jpeg" | "gif" | "bmp" | "ico" | "svg" | "webp" => Some('\u{F02E9}'), // nf-md-image
        "mp3" | "ogg" | "flac" | "wav" | "aac" | "m4a" => Some('\u{F04C3}'), // nf-md-music
        "mp4" | "avi" | "mkv" | "mov" | "wmv" | "webm" | "flv" => Some('\u{F0567}'), // nf-md-video
        _ => None,
    }
}

/// Get the file extension (lowercase, without the dot)
fn get_extension(name: &str) -> &str {
    if let Some(pos) = name.rfind('.') {
        if pos > 0 {
            return &name[pos+1..];
        }
    }
    ""
}

/// The icon for symlink arrow
pub fn symlink_arrow() -> char {
    '\u{F0054}' // nf-md-arrow_right_thin
}
