            } else if ft.is_socket() {
                NodeKind::Socket
            } else if ft.is_block_device() {
                NodeKind::BlockDevice
            } else if ft.is_char_device() {
                NodeKind::CharDevice
            } else {
                NodeKind::Unknown
            }
        };

