    Fifo,
    Socket,
    BlockDevice,
    CharDevice,
    File,
    None_,
    All,
}

impl NodeTypeFilter {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "dir" => Some(NodeTypeFilter::Dir),
            "symlink" => Some(NodeTypeFilter::Symlink),
            "fifo" => Some(NodeTypeFilter::Fifo),
            "socket" => Some(NodeTypeFilter::Socket),
            "block-device" => Some(NodeTypeFilter::BlockDevice),
            "char-device" => Some(NodeTypeFilter::CharDevice),
            "file" => Some(NodeTypeFilter::File),
            "none" => Some(NodeTypeFilter::None_),
            "all" => Some(NodeTypeFilter::All),
            _ => None,
        }
    }

    pub fn matches(&self, kind: &NodeKind) -> bool {
        match (self, kind) {
            (NodeTypeFilter::All, _) => true,
            (NodeTypeFilter::None_, _) => false,
            (NodeTypeFilter::Dir, NodeKind::Dir) => true,
            (NodeTypeFilter::Symlink, NodeKind::Symlink) => true,
            (NodeTypeFilter::File, NodeKind::File) => true,
