            "atime" => Some(SortField::Atime),
            "name" => Some(SortField::Name),
            "cname" => Some(SortField::Cname),
            "ext" => Some(SortField::Ext),
            "none" => Some(SortField::None_),
            "inode_" => Some(SortField::InodeR),
            "nlinks_" => Some(SortField::NlinksR),
            "typ_" => Some(SortField::TypR),
            "cat_" => Some(SortField::CatR),
            "user_" => Some(SortField::UserR),
            "uid_" => Some(SortField::UidR),
            "group_" => Some(SortField::GroupR),
            "gid_" => Some(SortField::GidR),
            "size_" => Some(SortField::SizeR),
            "blocks_" => Some(SortField::BlocksR),
            "btime_" => Some(SortField::BtimeR),
            "ctime_" => Some(SortField::CtimeR),
            "mtime_" => Some(SortField::MtimeR),
            "atime_" => Some(SortField::AtimeR),
            "name_" => Some(SortField::NameR),
            "cname_" => Some(SortField::CnameR),
            "ext_" => Some(SortField::ExtR),
            _ => None,
        }
    }
}

#[derive(Debug)]
pub struct DisplayOptions {
    pub detail_fields: Vec<DetailField>,
    pub show_header: bool,
    pub unit: String,
    pub grid: bool,
    pub down: bool,
    pub show_icons: bool,
    pub show_suffix: bool,
    pub show_sym: bool,
    pub collapse: bool,
    pub align: bool,
    pub type_filters: Vec<NodeTypeFilter>,
    pub imp_cutoff: i32,
    pub exclude: Option<regex::Regex>,
    pub only: Option<regex::Regex>,
    pub sort_fields: Vec<SortField>,
    pub use_color: bool,
    pub term_width: usize,
}

/// Get the "category" for sorting (dirs first)
fn node_category(kind: &NodeKind) -> u8 {
    match kind {
        NodeKind::Dir => 0,
        _ => 1,
    }
}

fn sort_nodes(nodes: &mut Vec<(Node, Vec<Node>)>, sort_fields: &[SortField]) {
    nodes.sort_by(|(a, _), (b, _)| {
        for field in sort_fields {
            let cmp = compare_nodes_by_field(a, b, field);
            if cmp != std::cmp::Ordering::Equal {
                return cmp;
            }
        }
        std::cmp::Ordering::Equal
    });
}

fn compare_nodes_by_field(a: &Node, b: &Node, field: &SortField) -> std::cmp::Ordering {
    use std::cmp::Ordering;

    match field {
        SortField::Cat | SortField::CatR => {
            let ca = node_category(&a.kind);
            let cb = node_category(&b.kind);
            let cmp = ca.cmp(&cb);
            if matches!(field, SortField::CatR) { cmp.reverse() } else { cmp }
        },
        SortField::Name | SortField::NameR => {
            let cmp = a.name.cmp(&b.name);
            if matches!(field, SortField::NameR) { cmp.reverse() } else { cmp }
        },
        SortField::Cname | SortField::CnameR => {
            let cmp = a.cname.cmp(&b.cname);
            if matches!(field, SortField::CnameR) { cmp.reverse() } else { cmp }
        },
        SortField::Ext | SortField::ExtR => {
            let cmp = a.ext.cmp(&b.ext);
            if matches!(field, SortField::ExtR) { cmp.reverse() } else { cmp }
        },
        SortField::Size | SortField::SizeR => {
            let cmp = a.size().cmp(&b.size());
            if matches!(field, SortField::SizeR) { cmp.reverse() } else { cmp }
        },
        SortField::Mtime | SortField::MtimeR => {
            let cmp = a.mtime().cmp(&b.mtime());
            if matches!(field, SortField::MtimeR) { cmp.reverse() } else { cmp }
        },
        SortField::Atime | SortField::AtimeR => {
            let cmp = a.atime().cmp(&b.atime());
            if matches!(field, SortField::AtimeR) { cmp.reverse() } else { cmp }
        },
        SortField::Ctime | SortField::CtimeR => {
            let cmp = a.ctime().cmp(&b.ctime());
            if matches!(field, SortField::CtimeR) { cmp.reverse() } else { cmp }
        },
        SortField::Btime | SortField::BtimeR => {
            let cmp = a.btime().cmp(&b.btime());
            if matches!(field, SortField::BtimeR) { cmp.reverse() } else { cmp }
        },
        SortField::Nlink | SortField::NlinksR => {
            let cmp = a.nlink().cmp(&b.nlink());
            if matches!(field, SortField::NlinksR) { cmp.reverse() } else { cmp }
        },
        SortField::Uid | SortField::UidR => {
            let cmp = a.uid().cmp(&b.uid());
            if matches!(field, SortField::UidR) { cmp.reverse() } else { cmp }
        },
        SortField::Gid | SortField::GidR => {
            let cmp = a.gid().cmp(&b.gid());
            if matches!(field, SortField::GidR) { cmp.reverse() } else { cmp }
        },
        SortField::Dev | SortField::DevR => {
            let cmp = a.dev().cmp(&b.dev());
            if matches!(field, SortField::DevR) { cmp.reverse() } else { cmp }
        },
        SortField::Ino | SortField::InodeR => {
            let cmp = a.ino().cmp(&b.ino());
            if matches!(field, SortField::InodeR) { cmp.reverse() } else { cmp }
        },
        SortField::Blocks | SortField::BlocksR => {
            let cmp = a.blocks().cmp(&b.blocks());
            if matches!(field, SortField::BlocksR) { cmp.reverse() } else { cmp }
        },
        SortField::Typ | SortField::TypR => {
            let cmp = (a.kind.type_char() as u8).cmp(&(b.kind.type_char() as u8));
            if matches!(field, SortField::TypR) { cmp.reverse() } else { cmp }
        },
        SortField::User | SortField::UserR => {
            let au = get_username(a.uid());
            let bu = get_username(b.uid());
            let cmp = au.cmp(&bu);
            if matches!(field, SortField::UserR) { cmp.reverse() } else { cmp }
        },
        SortField::Group | SortField::GroupR => {
            let ag = get_groupname(a.gid());
            let bg = get_groupname(b.gid());
            let cmp = ag.cmp(&bg);
            if matches!(field, SortField::GroupR) { cmp.reverse() } else { cmp }
        },
        SortField::None_ => std::cmp::Ordering::Equal,
    }
}

fn filter_type(kind: &NodeKind, filters: &[NodeTypeFilter]) -> bool {
    if filters.iter().any(|f| matches!(f, NodeTypeFilter::All)) {
        return true;
    }
    if filters.iter().any(|f| matches!(f, NodeTypeFilter::None_)) {
        return false;
    }
    filters.iter().any(|f| f.matches(kind))
}

fn get_username(uid: u32) -> String {
    users::get_user_by_uid(uid)
        .map(|u| u.name().to_string_lossy().to_string())
        .unwrap_or_else(|| uid.to_string())
}

fn get_groupname(gid: u32) -> String {
    users::get_group_by_gid(gid)
        .map(|g| g.name().to_string_lossy().to_string())
        .unwrap_or_else(|| gid.to_string())
}

pub fn list_path(path: &Path, opts: &DisplayOptions) -> Result<(), std::io::Error> {
    let metadata = fs::symlink_metadata(path)?;

    if metadata.is_dir() && !metadata.file_type().is_symlink() {
        list_dir(path, opts)
    } else {
        // Single file
        let node = Node::from_path(path, None)?;
        let nodes = vec![(node, vec![])];
        print_nodes(&nodes, opts, false);
        Ok(())
    }
}

fn list_dir(dir: &Path, opts: &DisplayOptions) -> Result<(), std::io::Error> {
    let entries = fs::read_dir(dir)?;
    let mut raw_nodes: Vec<Node> = Vec::new();

    for entry in entries {
        let entry = entry?;
        match Node::from_path(&entry.path(), Some(&entry.file_name().to_string_lossy())) {
            Ok(node) => raw_nodes.push(node),
            Err(_) => {} // Skip unreadable entries
        }
    }

    // Apply collapse: find Cargo.lock and place it as child of Cargo.toml
    let mut principal_nodes: Vec<(Node, Vec<Node>)> = Vec::new();

    if opts.collapse {
        // Find which nodes are children of others
        let cargo_lock_idx = raw_nodes.iter().position(|n| n.name == "Cargo.lock");
        let cargo_toml_idx = raw_nodes.iter().position(|n| n.name == "Cargo.toml");

        if let (Some(lock_idx), Some(toml_idx)) = (cargo_lock_idx, cargo_toml_idx) {
            // Extract Cargo.lock as child of Cargo.toml
            let lock_node = raw_nodes.remove(lock_idx);
            // Re-find toml_idx since we removed lock_idx
            let toml_idx = raw_nodes.iter().position(|n| n.name == "Cargo.toml").unwrap();
            let toml_node = raw_nodes.remove(toml_idx);

            // Add back remaining nodes
            for node in raw_nodes {
                principal_nodes.push((node, vec![]));
            }
            principal_nodes.push((toml_node, vec![lock_node]));
        } else {
            for node in raw_nodes {
                principal_nodes.push((node, vec![]));
            }
        }
    } else {
        for node in raw_nodes {
            principal_nodes.push((node, vec![]));
        }
    }

    // Sort
    sort_nodes(&mut principal_nodes, &opts.sort_fields);

    // Filter and display
    print_nodes(&principal_nodes, opts, true);

    Ok(())
}

struct NodeRender {
    /// Visual representation components
    prefix_chars: String,  // For collapsed items: "└─ "
    icon: Option<char>,
    dot_prefix: String,    // For alignment: " " or ""
    name_body: String,
    suffix: String,        // @ for symlinks, / for dirs
    sym_target: Option<String>,
    importance: i32,
    is_dir: bool,
    is_symlink: bool,
    is_special_dir: bool,  // like src/
}

fn get_decoration_level(importance: i32, cutoff: i32) -> i32 {
    importance - cutoff
}

fn print_nodes(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, is_dir_listing: bool) {
    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    // Check if any name starts with a dot (for alignment)
    let has_dot = opts.align && nodes.iter().any(|(n, _)| n.name.starts_with('.')) 
        || nodes.iter().any(|(_, children)| children.iter().any(|c| c.name.starts_with('.')));

    // Build rendered items list for detail view column widths
    let detail_fields = &opts.detail_fields;
    let has_details = !detail_fields.is_empty();

    if has_details {
        print_detail_view(nodes, opts, has_dot, &mut out);
    } else if opts.grid && opts.term_width < usize::MAX {
        print_grid_view(nodes, opts, has_dot, &mut out);
    } else {
        print_simple_view(nodes, opts, has_dot, &mut out);
    }
}

fn format_name_for_display(node: &Node, opts: &DisplayOptions, has_dot: bool, prefix: &str) -> String {
    let mut result = String::new();

    // Icon
    if opts.show_icons {
        let icon = icons::get_icon(&node.name, node.is_dir(), node.is_symlink());
        if let Some(icon_char) = icon {
            result.push(icon_char);
        } else {
            result.push(' ');
        }
        result.push(' ');
    }

    // Alignment for dot files
    if opts.align && has_dot && !node.name.starts_with('.') {
        result.push(' ');
    }

    // Name
    result.push_str(&node.name);

    // Suffix
    if opts.show_suffix {
        match &node.kind {
            NodeKind::Dir => result.push('/'),
            NodeKind::Symlink => result.push('@'),
            NodeKind::Fifo => result.push('|'),
            NodeKind::Socket => result.push('='),
            _ => {}
        }
    }

    // Symlink target
    if opts.show_sym && node.is_symlink() {
        if let Some(target) = &node.symlink_target {
            result.push(' ');
            result.push(icons::symlink_arrow());
            result.push(' ');
            result.push_str(target);
        }
    }

    result
}

fn render_name_colored(node: &Node, opts: &DisplayOptions, has_dot: bool, is_child: bool) -> String {
    if !opts.use_color {
        let mut result = String::new();

        if is_child {
            result.push_str("\u{2514}\u{2500} ");
        }

        // Icon
        if opts.show_icons {
            let icon = icons::get_icon(&node.name, node.is_dir(), node.is_symlink());
            if let Some(icon_char) = icon {
                result.push(icon_char);
            } else {
                result.push(' ');
            }
            result.push(' ');
        }

        // Alignment
        if opts.align && has_dot && !node.name.starts_with('.') {
            result.push(' ');
        }

        // Name
        result.push_str(&node.name);

        // Suffix
        if opts.show_suffix {
            match &node.kind {
                NodeKind::Dir => result.push('/'),
                NodeKind::Symlink => result.push('@'),
                NodeKind::Fifo => result.push('|'),
                NodeKind::Socket => result.push('='),
                _ => {}
            }
        }

        // Symlink target
        if opts.show_sym && node.is_symlink() {
            if let Some(target) = &node.symlink_target {
                result.push(' ');
                result.push(icons::symlink_arrow());
                result.push(' ');
                result.push_str(target);
            }
        }

        return result;
    }

    let dec_level = get_decoration_level(node.importance, opts.imp_cutoff);
    let mut result = String::new();

    if is_child {
        result.push_str("\u{2514}\u{2500} ");
    }

    // Build each component with appropriate colors
    let is_dotfile = node.name.starts_with('.');

    let name_color = get_name_color(node, dec_level);
    let icon_color = get_icon_color(node, dec_level);

    // Icon
    if opts.show_icons {
        let icon = icons::get_icon(&node.name, node.is_dir(), node.is_symlink());
        let icon_char = icon.unwrap_or(' ');

        if let Some(ic) = &icon_color {
            result.push_str(&format!("\x1b[{}m", ic));
        }
        result.push(icon_char);
        if icon_color.is_some() {
            result.push_str("\x1b[0m");
        }
        result.push(' ');
    }

    // Alignment
    if opts.align && has_dot && !is_dotfile {
        result.push(' ');
    }

    // Dot prefix for dotfiles
    if is_dotfile {
        let dot_color = get_dot_color(node, dec_level);
        if let Some(dc) = &dot_color {
            result.push_str(&format!("\x1b[{}m", dc));
        }
        result.push('.');
        if dot_color.is_some() {
            result.push_str("\x1b[0m");
        }
    }

    // Name body (without the dot)
    let name_body = if is_dotfile {
        &node.name[1..]
    } else {
        &node.name
    };

    if let Some(nc) = &name_color {
        result.push_str(&format!("\x1b[{}m", nc));
    }
    result.push_str(name_body);
    if name_color.is_some() {
        result.push_str("\x1b[0m");
    }

    // Suffix
    if opts.show_suffix {
        let suffix_color = get_suffix_color(node, dec_level);
        let suffix_char = match &node.kind {
            NodeKind::Dir => Some('/'),
            NodeKind::Symlink => Some('@'),
            NodeKind::Fifo => Some('|'),
            NodeKind::Socket => Some('='),
            _ => None,
        };
        if let Some(sc) = suffix_char {
            if let Some(scolor) = &suffix_color {
                result.push_str(&format!("\x1b[{}m", scolor));
            }
            result.push(sc);
            if suffix_color.is_some() {
                result.push_str("\x1b[0m");
            }
        }
    }

    // Symlink target
    if opts.show_sym && node.is_symlink() {
        if let Some(target) = &node.symlink_target {
            result.push(' ');
            result.push_str("\x1b[35m"); // magenta for arrow
            result.push(icons::symlink_arrow());
            result.push_str("\x1b[0m");
            result.push(' ');
            result.push_str(target);
        }
    }

    result
}

/// Get the color string for the icon based on node type and decoration level
fn get_icon_color(node: &Node, dec_level: i32) -> Option<String> {
    if dec_level < 0 { return None; } // hidden

    match &node.kind {
        NodeKind::Dir => {
            // Icon is always [34m] for dirs regardless of decoration level
            if node.name.starts_with('.') || dec_level == 0 {
                Some("2;34".to_string())
            } else {
                Some("34".to_string())
            }
        },
        _ => {
            // For files, icon color follows the base color
            let base = get_file_base_color(node);
            if dec_level == 0 {
                // Dim the base color
                if let Some(b) = base {
                    Some(format!("2;{}", b))
                } else {
                    Some("2".to_string())
                }
            } else if dec_level > 0 {
                if node.name.starts_with('.') {
                    // dotfiles are dim regardless
                    Some("2".to_string())
                } else {
                    base.map(|b| b.to_string())
                }
            } else {
                None
            }
        }
    }
}

/// Get the base color for a file type
fn get_file_base_color(node: &Node) -> Option<&'static str> {
    let ext = get_ext(&node.name);
    match ext {
        "rs" => Some("91"),  // bright red for Rust files
        _ => None,
    }
}

fn get_ext(name: &str) -> &str {
    if let Some(pos) = name.rfind('.') {
        if pos > 0 {
            return &name[pos+1..];
        }
    }
    ""
}

fn get_name_color(node: &Node, dec_level: i32) -> Option<String> {
    if dec_level < 0 { return None; } // hidden

    let is_dotfile = node.name.starts_with('.');

    match &node.kind {
        NodeKind::Dir => {
            if is_dotfile || dec_level == 0 {
                Some("2;34".to_string())
            } else {
                let style = match dec_level {
                    d if d >= 3 => "4;34",
                    2 => "3;34",
                    _ => "34",
                };
                Some(style.to_string())
            }
        },
        _ => {
            let base_color = get_file_base_color(node);

            if is_dotfile {
                // Dotfiles are dim
                if let Some(bc) = base_color {
                    Some(format!("2;{}", bc))
                } else {
                    Some("2".to_string())
                }
            } else if dec_level == 0 {
                // At cutoff, dim
                if let Some(bc) = base_color {
                    Some(format!("2;{}", bc))
                } else {
                    Some("2".to_string())
                }
            } else {
                // dec_level > 0
                let decoration = match dec_level {
                    d if d >= 3 => Some("4"),
                    2 => Some("3"),
                    _ => None,
                };

                match (decoration, base_color) {
                    (Some(d), Some(b)) => Some(format!("{};{}", d, b)),
                    (Some(d), None) => Some(d.to_string()),
                    (None, Some(b)) => Some(b.to_string()),
                    (None, None) => None,
                }
            }
        }
    }
}

fn get_dot_color(node: &Node, dec_level: i32) -> Option<String> {
    // Dot in dotfile names
    let base_color = get_file_base_color(node);
    if dec_level == 0 || node.name.starts_with('.') {
        if let Some(bc) = base_color {
            Some(format!("2;{}", bc))
        } else {
            Some("2".to_string())
        }
    } else {
        base_color.map(|b| b.to_string())
    }
}

fn get_suffix_color(node: &Node, dec_level: i32) -> Option<String> {
    match &node.kind {
        NodeKind::Dir => {
            if node.name.starts_with('.') || dec_level == 0 {
                Some("2;34".to_string())
            } else {
                // Suffix gets dim + dir style
                let style = match dec_level {
                    d if d >= 3 => "2;4;34",
                    2 => "2;3;34",
                    _ => "2;34",
                };
                Some(style.to_string())
            }
        },
        NodeKind::Symlink => {
            Some("2".to_string()) // @ is dimmed
        },
        _ => None,
    }
}

fn is_node_visible(node: &Node, opts: &DisplayOptions) -> bool {
    // Type filter
    if !filter_type(&node.kind, &opts.type_filters) {
        return false;
    }

    // Importance filter: hide if importance < cutoff
    if node.importance < opts.imp_cutoff {
        return false;
    }

    // Exclude pattern
    if let Some(excl) = &opts.exclude {
        if excl.is_match(&node.name) {
            return false;
        }
    }

    // Only pattern
    if let Some(only) = &opts.only {
        if !only.is_match(&node.name) {
            return false;
        }
    }

    true
}

fn print_simple_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    for (node, children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }

        let line = render_name_colored(node, opts, has_dot, false);
        writeln!(out, "{}", line).ok();

        // Print children (collapsed items)
        if opts.collapse {
            for child in children {
                if !is_node_visible(child, opts) {
                    continue;
                }
                let line = render_name_colored(child, opts, has_dot, true);
                writeln!(out, "{}", line).ok();
            }
        }
    }
}

fn print_grid_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    // Collect all visible items
    let mut items: Vec<String> = Vec::new();

    for (node, children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }
        // For grid, no collapse handling needed - just show the name
        let line = render_name_colored(node, opts, has_dot, false);
        items.push(line);

        // Don't show children in grid view
        // (though original might - let's skip for simplicity)
    }

    if items.is_empty() {
        return;
    }

    // Calculate column widths
    let term_width = opts.term_width;

    // Find max width of any item
    let max_item_width = items.iter().map(|s| visible_width(s)).max().unwrap_or(0);
    let col_width = max_item_width + 2; // 2 spaces padding between columns

    let num_cols = (term_width / col_width).max(1);
    let num_rows = (items.len() + num_cols - 1) / num_cols;

    if opts.down {
        // Column-first (down=true)
        for row in 0..num_rows {
            let mut line_parts: Vec<String> = Vec::new();
            for col in 0..num_cols {
                let idx = col * num_rows + row;
                if idx < items.len() {
                    let item = &items[idx];
                    let vw = visible_width(item);
                    let padding = if col < num_cols - 1 {
                        " ".repeat(col_width - vw)
                    } else {
                        String::new()
                    };
                    line_parts.push(format!("{}{}", item, padding));
                }
            }
            writeln!(out, "{}", line_parts.join("")).ok();
        }
    } else {
        // Row-first (default)
        for (i, item) in items.iter().enumerate() {
            let col = i % num_cols;
            let is_last = col == num_cols - 1 || i == items.len() - 1;

            if is_last {
                writeln!(out, "{}", item).ok();
            } else {
                let vw = visible_width(item);
                let padding = " ".repeat(col_width - vw);
                write!(out, "{}{}", item, padding).ok();
            }
        }
    }
}

fn visible_width(s: &str) -> usize {
    // Calculate visible width excluding ANSI escape codes
    let mut width = 0;
    let mut in_escape = false;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\x1b' && i + 1 < chars.len() && chars[i+1] == '[' {
            in_escape = true;
            i += 2;
        } else if in_escape {
            if chars[i].is_ascii_alphabetic() {
                in_escape = false;
            }
            i += 1;
        } else {
            // Count unicode character width
            use unicode_width::UnicodeWidthChar;
            width += chars[i].width().unwrap_or(0);
            i += 1;
        }
    }
    width
}

fn print_detail_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    let fields = &opts.detail_fields;
    let current_uid = unsafe { libc::getuid() };

    // Collect all visible nodes (with children)
    let mut visible_nodes: Vec<(&Node, bool)> = Vec::new(); // (node, is_child)
    for (node, children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }
        visible_nodes.push((node, false));
        if opts.collapse {
            for child in children {
                if !is_node_visible(child, opts) {
                    continue;
                }
                visible_nodes.push((child, true));
            }
        }
    }

    if visible_nodes.is_empty() {
        return;
    }

    // Pre-compute column data for alignment
    let mut col_data: Vec<Vec<String>> = Vec::new();
    for _ in fields {
        col_data.push(Vec::new());
    }

    for (node, _is_child) in &visible_nodes {
        for (j, field) in fields.iter().enumerate() {
            col_data[j].push(format_detail_value(node, field, opts));
        }
    }

    // Calculate column widths
    let mut col_widths: Vec<usize> = Vec::new();
    for (j, field) in fields.iter().enumerate() {
        let header_width = field.header().len();
        let max_data_width = col_data[j].iter().map(|s| s.len()).max().unwrap_or(0);
        col_widths.push(header_width.max(max_data_width));
    }

    // Print header
    if opts.show_header {
        let mut header = String::new();
        for (j, field) in fields.iter().enumerate() {
            let h = field.header();
            let w = col_widths[j];
            let padded = format!("{:<width$} ", h, width = w);
            if opts.use_color {
                header.push_str(&format!("\x1b[1;4;3m{}\x1b[0m", padded));
            } else {
                header.push_str(&padded);
            }
        }
        // Add "Name" header
        if opts.use_color {
            header.push_str("\x1b[1;4;3mName\x1b[0m");
        } else {
            header.push_str("Name");
        }
        writeln!(out, "{}", header).ok();
    }

    // Print data rows
    for (i, (node, is_child)) in visible_nodes.iter().enumerate() {
        let mut row = String::new();

        for (j, field) in fields.iter().enumerate() {
            let value = &col_data[j][i];
            let w = col_widths[j];

            // Format with right-alignment for numeric fields
            let formatted = match field {
                DetailField::Dev | DetailField::Ino | DetailField::Nlink |
                DetailField::Uid | DetailField::Gid | DetailField::Blocks => {
                    format!("{:>width$}", value, width = w)
                },
                DetailField::Size => {
                    // Size is right-aligned with special formatting
                    format!("{:>width$}", value, width = w)
                },
                _ => format!("{:<width$}", value, width = w),
            };

            if opts.use_color {
                let colored = colorize_detail_field(node, field, &formatted, opts, current_uid);
                row.push_str(&colored);
            } else {
                row.push_str(&formatted);
            }
            row.push(' ');
        }

        // Add name
        let name_rendered = render_name_colored(node, opts, has_dot, *is_child);
        row.push_str(&name_rendered);

        writeln!(out, "{}", row).ok();
    }
}

fn format_detail_value(node: &Node, field: &DetailField, opts: &DisplayOptions) -> String {
    match field {
        DetailField::Dev => node.dev().to_string(),
        DetailField::Ino => node.ino().to_string(),
        DetailField::Nlink => node.nlink().to_string(),
        DetailField::Typ => node.kind.type_char().to_string(),
        DetailField::Perm => format_permissions(node.permissions_mode()),
        DetailField::Oct => format_octal(node.permissions_mode()),
        DetailField::User => get_username(node.uid()),
        DetailField::Uid => node.uid().to_string(),
        DetailField::Group => get_groupname(node.gid()),
        DetailField::Gid => node.gid().to_string(),
        DetailField::Size => {
            if node.is_dir() {
                String::new()
            } else {
                format_size(node.size(), &opts.unit)
            }
        },
        DetailField::Blocks => {
            if node.is_dir() {
                String::new()
            } else {
                node.blocks().to_string()
            }
        },
        DetailField::Btime => format_time(node.btime().unwrap_or(0)),
        DetailField::Ctime => format_time(node.ctime()),
        DetailField::Mtime => format_time(node.mtime()),
        DetailField::Atime => format_time(node.atime()),
        DetailField::Git => "   ".to_string(), // placeholder
    }
}

fn format_permissions(mode: u32) -> String {
    let user_r = if mode & 0o400 != 0 { 'r' } else { '-' };
    let user_w = if mode & 0o200 != 0 { 'w' } else { '-' };
    let user_x = match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };
    let group_r = if mode & 0o040 != 0 { 'r' } else { '-' };
    let group_w = if mode & 0o020 != 0 { 'w' } else { '-' };
    let group_x = match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };
    let other_r = if mode & 0o004 != 0 { 'r' } else { '-' };
    let other_w = if mode & 0o002 != 0 { 'w' } else { '-' };
    let other_x = match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        (false, false) => '-',
    };

    format!("{}{}{} {}{}{} {}{}{}", 
        user_r, user_w, user_x,
        group_r, group_w, group_x, 
        other_r, other_w, other_x)
}

fn format_octal(mode: u32) -> String {
    let special = (mode >> 9) & 0o7;
    let user = (mode >> 6) & 0o7;
    let group = (mode >> 3) & 0o7;
    let other = mode & 0o7;

    if special > 0 {
        format!("{}{}{}{}", special, user, group, other)
    } else {
        format!(" {}{}{}", user, group, other)
    }
}

fn format_size(size: u64, unit: &str) -> String {
    match unit {
        "none" => format!("{} B", size),
        "decimal" => format_size_decimal(size),
        _ => format_size_binary(size), // "binary"
    }
}

fn format_size_binary(size: u64) -> String {
    const UNITS: &[(&str, u64)] = &[
        ("TiB", 1024 * 1024 * 1024 * 1024),
        ("GiB", 1024 * 1024 * 1024),
        ("MiB", 1024 * 1024),
        ("KiB", 1024),
    ];

    for (name, bytes) in UNITS {
        if size >= *bytes {
            let val = size as f64 / *bytes as f64;
            return format!("{:.1} {}", val, name);
        }
    }
    format!("{:.1}   B", size as f64)
}

fn format_size_decimal(size: u64) -> String {
    const UNITS: &[(&str, u64)] = &[
        ("TB", 1_000_000_000_000),
        ("GB", 1_000_000_000),
        ("MB", 1_000_000),
        ("kB", 1_000),
    ];

    for (name, bytes) in UNITS {
        if size >= *bytes {
            let val = size as f64 / *bytes as f64;
            return format!("{:.1}  {}", val, name);
        }
    }
    format!("{:.1}  B", size as f64)
}

fn format_time(timestamp: i64) -> String {
    use chrono::{DateTime, Local, TimeZone};
    let dt = Local.timestamp_opt(timestamp, 0).single().unwrap_or(Local::now());
    dt.format("%Y-%b-%d %I:%M%P").to_string()
}

fn colorize_detail_field(node: &Node, field: &DetailField, value: &str, opts: &DisplayOptions, current_uid: u32) -> String {
    match field {
        DetailField::Typ => {
            let color = match &node.kind {
                NodeKind::Dir => "34",      // blue
                NodeKind::File => "2",      // dim
                _ => "",                    // no color
            };
            if color.is_empty() {
                value.to_string()
            } else {
                format!("\x1b[{}m{}\x1b[0m", color, value)
            }
        },
        DetailField::Perm => colorize_permissions(node.permissions_mode()),
        DetailField::Oct => colorize_octal(node.permissions_mode()),
        DetailField::User => {
            if node.uid() == current_uid {
                format!("\x1b[1;34m{}\x1b[0m", value) // bold+blue for current user
            } else {
                format!("\x1b[2m{}\x1b[0m", value)    // dim for other users
            }
        },
        DetailField::Group => {
            format!("\x1b[2m{}\x1b[0m", value)         // dim for group
        },
        DetailField::Size => colorize_size(node, value, opts),
        DetailField::Mtime | DetailField::Atime | DetailField::Ctime | DetailField::Btime => {
            colorize_time(value)
        },
        _ => value.to_string(),
    }
}

fn colorize_permissions(mode: u32) -> String {
    let chars = format_permissions(mode);
    let mut result = String::new();

    for (i, ch) in chars.chars().enumerate() {
        if ch == ' ' {
            result.push(' ');
            continue;
        }

        let bit_pos = match i {
            0 => Some(8), // user r
            1 => Some(7), // user w
            2 => Some(6), // user x/s/S
            4 => Some(5), // group r
            5 => Some(4), // group w
            6 => Some(3), // group x/s/S
            8 => Some(2), // other r
            9 => Some(1), // other w
            10 => Some(0), // other x/t/T
            _ => None,
        };

        let color = match ch {
            'r' => "33",     // yellow
            'w' => "31",     // red
            'x' => "32",     // green
            's' | 'S' => "35", // magenta (setuid/setgid)
            't' | 'T' => "35", // magenta (sticky)
            '-' => "2",       // dim
            _ => "",
        };

        if color.is_empty() {
            result.push(ch);
        } else {
            result.push_str(&format!("\x1b[{}m{}\x1b[0m", color, ch));
        }
    }

    result
}

fn colorize_octal(mode: u32) -> String {
    // The SUGO column - simple display
    format_octal(mode)
}

fn colorize_size(node: &Node, value: &str, opts: &DisplayOptions) -> String {
    if node.is_dir() || value.is_empty() {
        return value.to_string();
    }

    // Parse the size string to colorize number vs unit
    // Format: "NNN.N XiB" or "NNN.N   B" or "NNN B"
    // Find where the number ends and unit begins
    let v = value.trim();

    // Find last space to split number and unit
    if let Some(space_pos) = v.rfind(' ') {
        let num_part = &v[..space_pos];
        let unit_part = &v[space_pos+1..];

        // Calculate leading spaces
        let leading = value.len() - v.len();
        let leading_str = " ".repeat(leading);

        return format!("{}\x1b[1m{}\x1b[0m \x1b[2m{}\x1b[0m", 
            leading_str, num_part.trim(), unit_part);
    }

    value.to_string()
}

fn colorize_time(value: &str) -> String {
    // Format: "2026-Apr-29 09:59am"
    // Date part gets bold+yellow, time part is plain
    if let Some(space_pos) = value.find(' ') {
        let date_part = &value[..space_pos];
        let time_part = &value[space_pos..];
        format!("\x1b[1;33m{}\x1b[0m{}", date_part, time_part)
    } else {
        value.to_string()
    }
}

fn get_username(uid: u32) -> String {
    users::get_user_by_uid(uid)
        .map(|u| u.name().to_string_lossy().to_string())
        .unwrap_or_else(|| uid.to_string())
}

fn get_groupname(gid: u32) -> String {
    users::get_group_by_gid(gid)
        .map(|g| g.name().to_string_lossy().to_string())
        .unwrap_or_else(|| gid.to_string())
}
