    fn regexec(preg: *const Regex, string: *const i8, nmatch: usize, 
               pmatch: *mut RegMatch, eflags: c_int) -> c_int;
    fn regfree(preg: *mut Regex);
    fn regerror(errcode: c_int, preg: *const Regex, errbuf: *mut i8, errbuf_size: usize) -> usize;
}

const REG_EXTENDED: c_int = 1;
const REG_ICASE: c_int = 2;
const REG_NOMATCH: c_int = 1;

