        let ret = regexec(&re, string.as_ptr() as *const i8, 1, &mut m, 0);
        if ret == 0 {
            println!("Match found!");
        } else if ret == REG_NOMATCH {
            println!("No match");
        }

        regfree(&mut re);
    }
}
