          gid_, size_, blocks_, btime_, ctime_, mtime_, atime_, name_, cname_, ext_, none]";

impl Args {
    pub fn parse() -> Result<Self, String> {
        let raw_args: Vec<String> = std::env::args().collect();
        let prog_name = raw_args.get(0).map(|s| s.as_str()).unwrap_or("pls");

        let mut args = Args {
            paths: Vec::new(),
            det: Vec::new(),
            header: true,
            unit: "binary".to_string(),
            grid: false,
            down: false,
            icon: true,
            suffix: true,
            sym: true,
            collapse: true,
            align: true,
            typ: vec![NodeTypeFilter::All],
            imp: 0,
            exclude: None,
            only: None,
            sort: vec![SortField::Cat, SortField::Cname],
        };

        let mut i = 1;
        while i < raw_args.len() {
            let arg = &raw_args[i];

            match arg.as_str() {
                "-h" => {
                    println!("{}", HELP_SHORT);
                    std::process::exit(0);
                },
                "--help" => {
                    println!("{}", HELP_LONG);
                    std::process::exit(0);
                },
                "-V" | "--version" => {
                    println!("pls {}", VERSION);
                    std::process::exit(0);
                },
                _ => {}
            }

            // Parse flags with values
            if arg.starts_with('-') {
                let (flag, val_opt) = split_flag(arg);

                match flag {
                    "-d" | "--det" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "DETAILS")?;
                        let spec = DetailSpec::from_str(&val).ok_or_else(|| {
                            format!(
                                "error: invalid value '{}' for '--det <DETAILS>'\n  [possible values: dev, ino, nlink, typ, perm, oct, user, uid, group, gid, size, blocks, btime, ctime, mtime, atime, git, none, std, all]\n\nFor more information, try '--help'.",
                                val
                            )
                        })?;
                        if let DetailSpec::None_ = &spec {
                            // none clears the list
                        } else {
                            args.det.push(spec);
                        }
                    },
                    "-H" | "--header" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "HEADER")?;
                        args.header = parse_bool(&val, flag)?;
                    },
                    "-u" | "--unit" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "UNIT")?;
                        if !matches!(val.as_str(), "binary" | "decimal" | "none") {
                            return Err(format!(
                                "error: invalid value '{}' for '--unit <UNIT>'\n  [possible values: binary, decimal, none]\n\nFor more information, try '--help'.",
                                val
                            ));
                        }
                        args.unit = val;
                    },
                    "-g" | "--grid" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "GRID")?;
                        args.grid = parse_bool(&val, flag)?;
                    },
                    "-D" | "--down" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "DOWN")?;
                        args.down = parse_bool(&val, flag)?;
                    },
                    "-i" | "--icon" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "ICON")?;
                        args.icon = parse_bool(&val, flag)?;
                    },
                    "-S" | "--suffix" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "SUFFIX")?;
                        args.suffix = parse_bool(&val, flag)?;
                    },
                    "-l" | "--sym" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "SYM")?;
                        args.sym = parse_bool(&val, flag)?;
                    },
                    "-c" | "--collapse" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "COLLAPSE")?;
                        args.collapse = parse_bool(&val, flag)?;
                    },
                    "-a" | "--align" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "ALIGN")?;
                        args.align = parse_bool(&val, flag)?;
                    },
                    "-t" | "--typ" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "TYPES")?;
                        let filter = NodeTypeFilter::from_str(&val).ok_or_else(|| {
                            format!(
                                "error: invalid value '{}' for '--typ <TYPES>'\n  [possible values: dir, symlink, fifo, socket, block-device, char-device, file, none, all]\n\nFor more information, try '--help'.",
                                val
                            )
                        })?;
                        // If this is the first explicit -t, clear the default "all"
                        if args.typ.len() == 1 && matches!(args.typ[0], NodeTypeFilter::All) {
                            args.typ.clear();
                        }
                        args.typ.push(filter);
                    },
                    "-I" | "--imp" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "IMP")?;
                        args.imp = val.parse::<i32>().map_err(|_| {
                            format!(
                                "error: invalid value '{}' for '--imp <IMP>': invalid digit found in string\n\nFor more information, try '--help'.",
                                val
                            )
                        })?;
                    },
                    "-e" | "--exclude" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "EXCLUDE")?;
                        // Validate regex
                        validate_regex(&val).map_err(|e| {
                            format!(
                                "error: invalid value '{}' for '--exclude <EXCLUDE>': {}\n\nFor more information, try '--help'.",
                                val, e
                            )
                        })?;
                        args.exclude = Some(val);
                    },
                    "-o" | "--only" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "ONLY")?;
                        // Validate regex
                        validate_regex(&val).map_err(|e| {
                            format!(
                                "error: invalid value '{}' for '--only <ONLY>': {}\n\nFor more information, try '--help'.",
                                val, e
                            )
                        })?;
                        args.only = Some(val);
                    },
                    "-s" | "--sort" => {
                        let val = get_value(&raw_args, &mut i, flag, val_opt, "SORT_BASES")?;
                        let sort_field = SortField::from_str(&val).ok_or_else(|| {
                            format!(
                                "error: invalid value '{}' for '--sort <SORT_BASES>'\n  [possible values: dev, ino, nlink, typ, cat, user, uid, group, gid, size, blocks, btime, ctime, mtime, atime, name, cname, ext, inode_, nlinks_, typ_, cat_, user_, uid_, group_, gid_, size_, blocks_, btime_, ctime_, mtime_, atime_, name_, cname_, ext_, none]\n\nFor more information, try '--help'.",
                                val
                            )
                        })?;
                        // Clear defaults on first explicit -s
                        if args.sort.len() == 2 
                            && matches!(args.sort[0], SortField::Cat)
                            && matches!(args.sort[1], SortField::Cname) {
                            args.sort.clear();
                        }
                        args.sort.push(sort_field);
                    },
                    _ => {
                        // Unknown flag - check if it looks like a short flag with value
                        if arg.starts_with('-') && !arg.starts_with("--") && arg.len() == 2 {
                            return Err(format!(
                                "error: unexpected argument '{}' found\n\nUsage: pls [OPTIONS] [PATHS]...\n\nFor more information, try '--help'.",
                                arg
                            ));
                        }
                        return Err(format!(
                            "error: unexpected argument '{}' found\n\nUsage: pls [OPTIONS] [PATHS]...\n\nFor more information, try '--help'.",
                            arg
                        ));
                    }
                }
            } else if arg == "--" {
                // Everything after -- is a positional arg
                i += 1;
                while i < raw_args.len() {
                    args.paths.push(PathBuf::from(&raw_args[i]));
                    i += 1;
                }
                break;
            } else {
                args.paths.push(PathBuf::from(arg));
            }

            i += 1;
        }

        // Set default path if none provided
        if args.paths.is_empty() {
            args.paths.push(PathBuf::from("."));
        }

        Ok(args)
    }
}

fn split_flag(arg: &str) -> (&str, Option<String>) {
    if let Some(pos) = arg.find('=') {
        (&arg[..pos], Some(arg[pos+1..].to_string()))
    } else {
        (arg, None)
    }
}

fn get_value(args: &[String], i: &mut usize, flag: &str, val_opt: Option<String>, name: &str) -> Result<String, String> {
    if let Some(val) = val_opt {
        return Ok(val);
    }
    *i += 1;
    if *i < args.len() {
        let next = &args[*i];
        // Don't consume another flag as a value
        if next.starts_with('-') && next.len() > 1 && !next.chars().nth(1).map(|c| c.is_ascii_digit()).unwrap_or(false) {
            // Check if it could be a negative number
            let is_negative_num = next.starts_with('-') && next.len() > 1 && next[1..].chars().all(|c| c.is_ascii_digit());
            if !is_negative_num {
                *i -= 1;
                return Err(format!(
                    "error: a value is required for '{}' but none was supplied\n  [possible values: true, false]\n\nFor more information, try '--help'.",
                    flag
                ));
            }
        }
        Ok(next.clone())
    } else {
        Err(format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.",
            flag
        ))
    }
}

fn parse_bool(s: &str, flag: &str) -> Result<bool, String> {
    match s {
        "true" => Ok(true),
        "false" => Ok(false),
        v => Err(format!(
            "error: invalid value '{}' for '{}'\n  [possible values: true, false]\n\nFor more information, try '--help'.",
            v, flag
        )),
    }
}

fn validate_regex(pattern: &str) -> Result<(), String> {
    use std::ffi::CString;
    use std::os::raw::c_int;

    extern "C" {
        fn regcomp(preg: *mut [u8; 128], pattern: *const i8, cflags: c_int) -> c_int;
        fn regfree(preg: *mut [u8; 128]);
        fn regerror(errcode: c_int, preg: *const [u8; 128], errbuf: *mut i8, errbuf_size: usize) -> usize;
    }

    const REG_EXTENDED: c_int = 1;

    let c_pat = CString::new(pattern).map_err(|e| e.to_string())?;

    unsafe {
        let mut re: [u8; 128] = std::mem::zeroed();
        let ret = regcomp(&mut re, c_pat.as_ptr() as *const i8, REG_EXTENDED);
        if ret != 0 {
            // Get error message
            let mut buf = [0i8; 256];
            regerror(ret, &re, buf.as_mut_ptr(), buf.len());
            regfree(&mut re);

            // Try to format like Rust regex error
            let errmsg = std::ffi::CStr::from_ptr(buf.as_ptr())
                .to_string_lossy()
                .to_string();

            // Build a similar format to the regex crate's error
            let spaces = " ".repeat(pattern.len());
            return Err(format!(
                "regex parse error:\n    {}\n    ^\nerror: {}",
                pattern, errmsg
            ));
        }
        regfree(&mut re);
    }

    Ok(())
}
RUSTEOF

