fn split_flag(arg: &str) -> (&str, Option<String>) {
    if let Some(pos) = arg.find('=') {
        (&arg[..pos], Some(arg[pos+1..].to_string()))
    } else {
        (arg, None)
    }
}

fn get_value(args: &[String], i: &mut usize, flag: &str, val_opt: Option<String>, name: &str) -> Result<String, String> {
    if let Some(val) = val_opt {
        return Ok(val);
    }
    *i += 1;
    if *i < args.len() {
        let next = &args[*i];
        // Don't consume another flag as a value
        if next.starts_with('-') && next.len() > 1 && !next.chars().nth(1).map(|c| c.is_ascii_digit()).unwrap_or(false) {
            // Check if it could be a negative number
            let is_negative_num = next.starts_with('-') && next.len() > 1 && next[1..].chars().all(|c| c.is_ascii_digit());
            if !is_negative_num {
                *i -= 1;
                return Err(format!(
                    "error: a value is required for '{}' but none was supplied\n  [possible values: true, false]\n\nFor more information, try '--help'.",
                    flag
                ));
            }
        }
        Ok(next.clone())
    } else {
        Err(format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.",
            flag
        ))
    }
}

fn parse_bool(s: &str, flag: &str) -> Result<bool, String> {
    match s {
        "true" => Ok(true),
        "false" => Ok(false),
        v => Err(format!(
            "error: invalid value '{}' for '{}'\n  [possible values: true, false]\n\nFor more information, try '--help'.",
            v, flag
        )),
    }
}

fn validate_regex(pattern: &str) -> Result<(), String> {
    use std::ffi::CString;
    use std::os::raw::c_int;

    extern "C" {
        fn regcomp(preg: *mut [u8; 128], pattern: *const i8, cflags: c_int) -> c_int;
        fn regfree(preg: *mut [u8; 128]);
        fn regerror(errcode: c_int, preg: *const [u8; 128], errbuf: *mut i8, errbuf_size: usize) -> usize;
    }

    const REG_EXTENDED: c_int = 1;

    let c_pat = CString::new(pattern).map_err(|e| e.to_string())?;

    unsafe {
        let mut re: [u8; 128] = std::mem::zeroed();
        let ret = regcomp(&mut re, c_pat.as_ptr() as *const i8, REG_EXTENDED);
        if ret != 0 {
            // Get error message
            let mut buf = [0i8; 256];
            regerror(ret, &re, buf.as_mut_ptr(), buf.len());
            regfree(&mut re);

            // Try to format like Rust regex error
            let errmsg = std::ffi::CStr::from_ptr(buf.as_ptr())
                .to_string_lossy()
                .to_string();

            // Build a similar format to the regex crate's error
            let spaces = " ".repeat(pattern.len());
            return Err(format!(
                "regex parse error:\n    {}\n    ^\nerror: {}",
                pattern, errmsg
            ));
        }
        regfree(&mut re);
    }

    Ok(())
}
