fn list_dir(dir: &Path, opts: &DisplayOptions) -> Result<(), std::io::Error> {
    let entries = fs::read_dir(dir)?;
    let mut raw_nodes: Vec<Node> = Vec::new();

    for entry in entries {
        let entry = entry?;
        match Node::from_path(&entry.path(), Some(&entry.file_name().to_string_lossy())) {
            Ok(node) => raw_nodes.push(node),
            Err(_) => {}
        }
    }

    // Apply collapse: find Cargo.lock and place it as child of Cargo.toml
    let mut principal_nodes: Vec<(Node, Vec<Node>)> = Vec::new();

    if opts.collapse {
        let cargo_lock_idx = raw_nodes.iter().position(|n| n.name == "Cargo.lock");
        let cargo_toml_idx = raw_nodes.iter().position(|n| n.name == "Cargo.toml");

        if let (Some(lock_idx), Some(_)) = (cargo_lock_idx, cargo_toml_idx) {
            let lock_node = raw_nodes.remove(lock_idx);
            let toml_idx = raw_nodes.iter().position(|n| n.name == "Cargo.toml").unwrap();
            let toml_node = raw_nodes.remove(toml_idx);

            for node in raw_nodes {
                principal_nodes.push((node, vec![]));
            }
            principal_nodes.push((toml_node, vec![lock_node]));
        } else {
            for node in raw_nodes {
                principal_nodes.push((node, vec![]));
            }
        }
    } else {
        for node in raw_nodes {
            principal_nodes.push((node, vec![]));
        }
    }

    // Sort
    sort_nodes(&mut principal_nodes, &opts.sort_fields);

    // Display
    let has_dot = opts.align && (
        principal_nodes.iter().any(|(n, _)| n.name.starts_with('.'))
        || principal_nodes.iter().any(|(_, children)| children.iter().any(|c| c.name.starts_with('.')))
    );

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    let has_details = !opts.detail_fields.is_empty();

    if has_details {
        print_detail_view(&principal_nodes, opts, has_dot, &mut out);
    } else if opts.grid && opts.term_width < usize::MAX {
        print_grid_view(&principal_nodes, opts, has_dot, &mut out);
    } else {
        print_simple_view(&principal_nodes, opts, has_dot, &mut out);
    }

    Ok(())
}

fn node_category(kind: &NodeKind) -> u8 {
    match kind {
        NodeKind::Dir => 0,
        _ => 1,
    }
}

fn sort_nodes(nodes: &mut Vec<(Node, Vec<Node>)>, sort_fields: &[SortField]) {
    nodes.sort_by(|(a, _), (b, _)| {
        for field in sort_fields {
            let cmp = compare_nodes_by_field(a, b, field);
            if cmp != std::cmp::Ordering::Equal {
                return cmp;
            }
        }
        std::cmp::Ordering::Equal
    });
}

fn compare_nodes_by_field(a: &Node, b: &Node, field: &SortField) -> std::cmp::Ordering {
    match field {
        SortField::Cat => node_category(&a.kind).cmp(&node_category(&b.kind)),
        SortField::CatR => node_category(&b.kind).cmp(&node_category(&a.kind)),
        SortField::Name => a.name.cmp(&b.name),
        SortField::NameR => b.name.cmp(&a.name),
        SortField::Cname => a.cname.cmp(&b.cname),
        SortField::CnameR => b.cname.cmp(&a.cname),
        SortField::Ext => a.ext.cmp(&b.ext),
        SortField::ExtR => b.ext.cmp(&a.ext),
        SortField::Size => a.size().cmp(&b.size()),
        SortField::SizeR => b.size().cmp(&a.size()),
        SortField::Mtime => a.mtime().cmp(&b.mtime()),
        SortField::MtimeR => b.mtime().cmp(&a.mtime()),
        SortField::Atime => a.atime().cmp(&b.atime()),
        SortField::AtimeR => b.atime().cmp(&a.atime()),
        SortField::Ctime => a.ctime().cmp(&b.ctime()),
        SortField::CtimeR => b.ctime().cmp(&a.ctime()),
        SortField::Btime => a.btime().cmp(&b.btime()),
        SortField::BtimeR => b.btime().cmp(&a.btime()),
        SortField::Nlink => a.nlink().cmp(&b.nlink()),
        SortField::NlinksR => b.nlink().cmp(&a.nlink()),
        SortField::Uid => a.uid().cmp(&b.uid()),
        SortField::UidR => b.uid().cmp(&a.uid()),
        SortField::Gid => a.gid().cmp(&b.gid()),
        SortField::GidR => b.gid().cmp(&a.gid()),
        SortField::Dev => a.dev().cmp(&b.dev()),
        SortField::DevR => b.dev().cmp(&a.dev()),
        SortField::Ino => a.ino().cmp(&b.ino()),
        SortField::InodeR => b.ino().cmp(&a.ino()),
        SortField::Blocks => a.blocks().cmp(&b.blocks()),
        SortField::BlocksR => b.blocks().cmp(&a.blocks()),
        SortField::Typ => (a.kind.type_char() as u8).cmp(&(b.kind.type_char() as u8)),
        SortField::TypR => (b.kind.type_char() as u8).cmp(&(a.kind.type_char() as u8)),
        SortField::User => get_username(a.uid()).cmp(&get_username(b.uid())),
        SortField::UserR => get_username(b.uid()).cmp(&get_username(a.uid())),
        SortField::Group => get_groupname(a.gid()).cmp(&get_groupname(b.gid())),
        SortField::GroupR => get_groupname(b.gid()).cmp(&get_groupname(a.gid())),
        SortField::None_ => std::cmp::Ordering::Equal,
    }
}

fn filter_type(kind: &NodeKind, filters: &[NodeTypeFilter]) -> bool {
    if filters.iter().any(|f| matches!(f, NodeTypeFilter::All)) {
        return true;
    }
    if filters.iter().any(|f| matches!(f, NodeTypeFilter::None_)) {
        return false;
    }
    filters.iter().any(|f| f.matches(kind))
}

fn is_node_visible(node: &Node, opts: &DisplayOptions) -> bool {
    if !filter_type(&node.kind, &opts.type_filters) {
        return false;
    }
    if node.importance < opts.imp_cutoff {
        return false;
    }
    if let Some(excl) = &opts.exclude {
        if regex_is_match(excl, &node.name) {
            return false;
        }
    }
    if let Some(only) = &opts.only {
        if !regex_is_match(only, &node.name) {
            return false;
        }
    }
    true
}

fn regex_is_match(pattern: &str, text: &str) -> bool {
    extern "C" {
        fn regcomp(preg: *mut [u8; 128], pattern: *const i8, cflags: c_int) -> c_int;
        fn regexec(preg: *const [u8; 128], string: *const i8, nmatch: usize,
                   pmatch: *mut [i64; 2], eflags: c_int) -> c_int;
        fn regfree(preg: *mut [u8; 128]);
    }

    const REG_EXTENDED: c_int = 1;

    let c_pat = match CString::new(pattern) {
        Ok(p) => p,
        Err(_) => return false,
    };
    let c_text = match CString::new(text) {
        Ok(t) => t,
        Err(_) => return false,
    };

    unsafe {
        let mut re: [u8; 128] = std::mem::zeroed();
        if regcomp(&mut re, c_pat.as_ptr() as *const i8, REG_EXTENDED) != 0 {
            return false;
        }
        let mut m: [i64; 2] = [0; 2];
        let result = regexec(&re, c_text.as_ptr() as *const i8, 1, &mut m, 0);
        regfree(&mut re);
        result == 0
    }
}

fn render_name_colored(node: &Node, opts: &DisplayOptions, has_dot: bool, is_child: bool) -> String {
    let dec_level = node.importance - opts.imp_cutoff;
    let is_dotfile = node.name.starts_with('.');
    let mut result = String::new();

    if is_child {
        result.push('\u{2514}');
        result.push('\u{2500}');
        result.push(' ');
    }

    let icon = if opts.show_icons {
        Some(icons::get_icon(&node.name, node.is_dir(), node.is_symlink())
            .unwrap_or(' '))
    } else {
        None
    };

    if opts.use_color {
        // Icon with color
        if let Some(ic) = icon {
            let ic_color = get_icon_color(node, dec_level);
            if let Some(ref c) = ic_color {
                result.push_str(&format!("\x1b[{}m", c));
            }
            result.push(ic);
            if ic_color.is_some() {
                result.push_str("\x1b[0m");
            }
            result.push(' ');
        }

        // Alignment
        if opts.align && has_dot && !is_dotfile {
            result.push(' ');
        }

        // Dot for dotfiles
        if is_dotfile {
            let dot_color = get_dim_or_color(node, dec_level);
            if let Some(ref c) = dot_color {
                result.push_str(&format!("\x1b[{}m", c));
            }
            result.push('.');
            if dot_color.is_some() {
                result.push_str("\x1b[0m");
            }
        }

        // Name body
        let name_body = if is_dotfile { &node.name[1..] } else { &node.name };
        let name_color = get_name_color(node, dec_level);
        if let Some(ref c) = name_color {
            result.push_str(&format!("\x1b[{}m", c));
        }
        result.push_str(name_body);
        if name_color.is_some() {
            result.push_str("\x1b[0m");
        }

        // Suffix
        if opts.show_suffix {
            let suffix_char = get_suffix_char(&node.kind);
            if let Some(sc) = suffix_char {
                let suf_color = get_suffix_color(node, dec_level);
                if let Some(ref c) = suf_color {
                    result.push_str(&format!("\x1b[{}m", c));
                }
                result.push(sc);
                if suf_color.is_some() {
                    result.push_str("\x1b[0m");
                }
            }
        }

        // Symlink target
        if opts.show_sym && node.is_symlink() {
            if let Some(target) = &node.symlink_target {
                result.push(' ');
                result.push_str("\x1b[35m");
                result.push(icons::symlink_arrow());
                result.push_str("\x1b[0m");
                result.push(' ');
                result.push_str(target);
            }
        }
    } else {
        // No color mode
        if let Some(ic) = icon {
            result.push(ic);
            result.push(' ');
        }

        if opts.align && has_dot && !is_dotfile {
            result.push(' ');
        }

        result.push_str(&node.name);

        if opts.show_suffix {
            if let Some(sc) = get_suffix_char(&node.kind) {
                result.push(sc);
            }
        }

        if opts.show_sym && node.is_symlink() {
            if let Some(target) = &node.symlink_target {
                result.push(' ');
                result.push(icons::symlink_arrow());
                result.push(' ');
                result.push_str(target);
            }
        }
    }

    result
}

fn get_suffix_char(kind: &NodeKind) -> Option<char> {
    match kind {
        NodeKind::Dir => Some('/'),
        NodeKind::Symlink => Some('@'),
        NodeKind::Fifo => Some('|'),
        NodeKind::Socket => Some('='),
        _ => None,
    }
}

fn get_file_base_color(node: &Node) -> Option<&'static str> {
    let ext = get_ext(&node.name);
    match ext {
        "rs" => Some("91"),
        _ => None,
    }
}

fn get_ext(name: &str) -> &str {
    if let Some(pos) = name.rfind('.') {
        if pos > 0 {
            return &name[pos+1..];
        }
    }
    ""
}

fn get_icon_color(node: &Node, dec_level: i32) -> Option<String> {
    if dec_level < 0 { return None; }

    let is_dotfile = node.name.starts_with('.');

    match &node.kind {
        NodeKind::Dir => {
            if is_dotfile || dec_level == 0 {
                Some("2;34".to_string())
            } else {
                Some("34".to_string())
            }
        },
        _ => {
            let base = get_file_base_color(node);
            if is_dotfile || dec_level == 0 {
                if let Some(b) = base {
                    Some(format!("2;{}", b))
                } else {
                    Some("2".to_string())
                }
            } else {
                base.map(|b| b.to_string())
            }
        }
    }
}

fn get_dim_or_color(node: &Node, dec_level: i32) -> Option<String> {
    let base = get_file_base_color(node);
    let is_dotfile = node.name.starts_with('.');

    if is_dotfile || dec_level == 0 {
        if let Some(b) = base {
            Some(format!("2;{}", b))
        } else {
            Some("2".to_string())
        }
    } else {
        base.map(|b| b.to_string())
    }
}

fn get_name_color(node: &Node, dec_level: i32) -> Option<String> {
    if dec_level < 0 { return None; }

    let is_dotfile = node.name.starts_with('.');

    match &node.kind {
        NodeKind::Dir => {
            if is_dotfile {
                Some("2;34".to_string())
            } else if dec_level == 0 {
                Some("2;34".to_string())
            } else {
                let style = match dec_level {
                    d if d >= 3 => "4;34",
                    2 => "3;34",
                    _ => "34",
                };
                Some(style.to_string())
            }
        },
        _ => {
            let base_color = get_file_base_color(node);

            if is_dotfile {
                if let Some(bc) = base_color {
                    Some(format!("2;{}", bc))
                } else {
                    Some("2".to_string())
                }
            } else if dec_level == 0 {
                if let Some(bc) = base_color {
                    Some(format!("2;{}", bc))
                } else {
                    Some("2".to_string())
                }
            } else {
                let decoration = match dec_level {
                    d if d >= 3 => Some("4"),
                    2 => Some("3"),
                    _ => None,
                };

                match (decoration, base_color) {
                    (Some(d), Some(b)) => Some(format!("{};{}", d, b)),
                    (Some(d), None) => Some(d.to_string()),
                    (None, Some(b)) => Some(b.to_string()),
                    (None, None) => None,
                }
            }
        }
    }
}

fn get_suffix_color(node: &Node, dec_level: i32) -> Option<String> {
    match &node.kind {
        NodeKind::Dir => {
            let is_dotfile = node.name.starts_with('.');
            if is_dotfile || dec_level == 0 {
                Some("2;34".to_string())
            } else {
                let style = match dec_level {
                    d if d >= 3 => "2;4;34",
                    2 => "2;3;34",
                    _ => "2;34",
                };
                Some(style.to_string())
            }
        },
        NodeKind::Symlink => Some("2".to_string()),
        _ => None,
    }
}

fn print_simple_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    for (node, children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }

        let line = render_name_colored(node, opts, has_dot, false);
        writeln!(out, "{}", line).ok();

        if opts.collapse {
            for child in children {
                if !is_node_visible(child, opts) {
                    continue;
                }
                let line = render_name_colored(child, opts, has_dot, true);
                writeln!(out, "{}", line).ok();
            }
        }
    }
}

fn print_grid_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    let mut items: Vec<String> = Vec::new();

    for (node, _children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }
        let line = render_name_colored(node, opts, has_dot, false);
        items.push(line);
    }

    if items.is_empty() {
        return;
    }

    let term_width = opts.term_width;
    let max_item_width = items.iter().map(|s| visible_width(s)).max().unwrap_or(0);
    let col_width = max_item_width + 2;
    let num_cols = (term_width / col_width).max(1);
    let num_rows = (items.len() + num_cols - 1) / num_cols;

    if opts.down {
        for row in 0..num_rows {
            let mut line_parts: Vec<String> = Vec::new();
            for col in 0..num_cols {
                let idx = col * num_rows + row;
                if idx < items.len() {
                    let item = &items[idx];
                    let vw = visible_width(item);
                    let is_last = col == num_cols - 1 || idx + num_rows >= items.len();
                    if !is_last {
                        let padding = " ".repeat(col_width.saturating_sub(vw));
                        line_parts.push(format!("{}{}", item, padding));
                    } else {
                        line_parts.push(item.clone());
                    }
                }
            }
            writeln!(out, "{}", line_parts.join("")).ok();
        }
    } else {
        for (i, item) in items.iter().enumerate() {
            let col = i % num_cols;
            let is_last_in_row = col == num_cols - 1;
            let is_last = i == items.len() - 1;

            if is_last_in_row || is_last {
                writeln!(out, "{}", item).ok();
            } else {
                let vw = visible_width(item);
                let padding = " ".repeat(col_width.saturating_sub(vw));
                write!(out, "{}{}", item, padding).ok();
            }
        }
    }
}

fn visible_width(s: &str) -> usize {
    let mut width = 0;
    let mut in_escape = false;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\x1b' && i + 1 < chars.len() && chars[i+1] == '[' {
            in_escape = true;
            i += 2;
        } else if in_escape {
            if chars[i].is_ascii_alphabetic() {
                in_escape = false;
            }
            i += 1;
        } else {
            // Estimate width: 1 for ASCII, 2 for wide chars, 1 otherwise
            let c = chars[i];
            let w = if (c as u32) < 0x80 {
                1
            } else if is_wide_char(c) {
                2
            } else {
                1
            };
            width += w;
            i += 1;
        }
    }
    width
}

fn is_wide_char(c: char) -> bool {
    let code = c as u32;
    // Common wide character ranges
    (code >= 0x1100 && code <= 0x115F) ||  // Hangul
    (code >= 0x2E80 && code <= 0x9FFF) ||  // CJK
    (code >= 0xF900 && code <= 0xFAFF) ||  // CJK compatibility
    (code >= 0xFE30 && code <= 0xFE4F) ||  // CJK compatibility forms
    (code >= 0xFF00 && code <= 0xFF60) ||  // Fullwidth
    (code >= 0xFFE0 && code <= 0xFFE6)     // Fullwidth
}

fn print_detail_view(nodes: &[(Node, Vec<Node>)], opts: &DisplayOptions, has_dot: bool, out: &mut impl Write) {
    let fields = &opts.detail_fields;
    let current_uid = get_current_uid();

    let mut visible_nodes: Vec<(&Node, bool)> = Vec::new();
    for (node, children) in nodes {
        if !is_node_visible(node, opts) {
            continue;
        }
        visible_nodes.push((node, false));
        if opts.collapse {
            for child in children {
                if !is_node_visible(child, opts) {
                    continue;
                }
                visible_nodes.push((child, true));
            }
        }
    }

    if visible_nodes.is_empty() {
        return;
    }

    // Pre-compute column data
    let mut col_data: Vec<Vec<String>> = Vec::new();
    for _ in fields {
        col_data.push(Vec::new());
    }

    for (node, _) in &visible_nodes {
        for (j, field) in fields.iter().enumerate() {
            col_data[j].push(format_detail_value(node, field, opts));
        }
    }

    // Calculate column widths
    let mut col_widths: Vec<usize> = Vec::new();
    for (j, field) in fields.iter().enumerate() {
        let header_width = field.header().len();
        let max_data_width = col_data[j].iter().map(|s| s.len()).max().unwrap_or(0);
        col_widths.push(header_width.max(max_data_width));
    }

    // Print header
    if opts.show_header {
        let mut header = String::new();
        for (j, field) in fields.iter().enumerate() {
            let h = field.header();
            let w = col_widths[j];
            let padded = format!("{:<width$} ", h, width = w);
            if opts.use_color {
                header.push_str(&format!("\x1b[1;4;3m{}\x1b[0m", padded));
            } else {
                header.push_str(&padded);
            }
        }
        if opts.use_color {
            header.push_str("\x1b[1;4;3mName\x1b[0m");
        } else {
            header.push_str("Name");
        }
        writeln!(out, "{}", header).ok();
    }

    // Print data rows
    for (i, (node, is_child)) in visible_nodes.iter().enumerate() {
        let mut row = String::new();

        for (j, field) in fields.iter().enumerate() {
            let value = &col_data[j][i];
            let w = col_widths[j];

            let is_right_aligned = matches!(field,
                DetailField::Dev | DetailField::Ino | DetailField::Nlink |
                DetailField::Uid | DetailField::Gid | DetailField::Blocks |
                DetailField::Size
            );

            let formatted = if is_right_aligned {
                format!("{:>width$}", value, width = w)
            } else {
                format!("{:<width$}", value, width = w)
            };

            if opts.use_color {
                let colored = colorize_detail_field(node, field, &formatted, opts, current_uid);
                row.push_str(&colored);
            } else {
                row.push_str(&formatted);
            }
            row.push(' ');
        }

        let name_rendered = render_name_colored(node, opts, has_dot, *is_child);
        row.push_str(&name_rendered);

        writeln!(out, "{}", row).ok();
    }
}

fn format_detail_value(node: &Node, field: &DetailField, opts: &DisplayOptions) -> String {
    match field {
        DetailField::Dev => node.dev().to_string(),
        DetailField::Ino => node.ino().to_string(),
        DetailField::Nlink => node.nlink().to_string(),
        DetailField::Typ => node.kind.type_char().to_string(),
        DetailField::Perm => format_permissions(node.permissions_mode()),
        DetailField::Oct => format_octal(node.permissions_mode()),
        DetailField::User => get_username(node.uid()),
        DetailField::Uid => node.uid().to_string(),
        DetailField::Group => get_groupname(node.gid()),
        DetailField::Gid => node.gid().to_string(),
        DetailField::Size => {
            if node.is_dir() {
                String::new()
            } else {
                format_size(node.size(), &opts.unit)
            }
        },
        DetailField::Blocks => {
            if node.is_dir() {
                String::new()
            } else {
                node.blocks().to_string()
            }
        },
        DetailField::Btime => format_time(node.btime().unwrap_or(0)),
        DetailField::Ctime => format_time(node.ctime()),
        DetailField::Mtime => format_time(node.mtime()),
        DetailField::Atime => format_time(node.atime()),
        DetailField::Git => "   ".to_string(),
    }
}

fn format_permissions(mode: u32) -> String {
    let user_r = if mode & 0o400 != 0 { 'r' } else { '-' };
    let user_w = if mode & 0o200 != 0 { 'w' } else { '-' };
    let user_x = match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };
    let group_r = if mode & 0o040 != 0 { 'r' } else { '-' };
    let group_w = if mode & 0o020 != 0 { 'w' } else { '-' };
    let group_x = match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };
    let other_r = if mode & 0o004 != 0 { 'r' } else { '-' };
    let other_w = if mode & 0o002 != 0 { 'w' } else { '-' };
    let other_x = match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        (false, false) => '-',
    };

    format!("{}{}{} {}{}{} {}{}{}", 
        user_r, user_w, user_x,
        group_r, group_w, group_x, 
        other_r, other_w, other_x)
}

fn format_octal(mode: u32) -> String {
    let special = (mode >> 9) & 0o7;
    let user = (mode >> 6) & 0o7;
    let group = (mode >> 3) & 0o7;
    let other = mode & 0o7;

    if special > 0 {
        format!("{}{}{}{}", special, user, group, other)
    } else {
        format!(" {}{}{}", user, group, other)
    }
}

fn format_size(size: u64, unit: &str) -> String {
    match unit {
        "none" => format!("{} B", size),
        "decimal" => format_size_decimal(size),
        _ => format_size_binary(size),
    }
}

fn format_size_binary(size: u64) -> String {
    const UNITS: &[(&str, u64)] = &[
        ("TiB", 1u64 << 40),
        ("GiB", 1u64 << 30),
        ("MiB", 1u64 << 20),
        ("KiB", 1u64 << 10),
    ];

    for (name, bytes) in UNITS {
        if size >= *bytes {
            let val = size as f64 / *bytes as f64;
            return format!("{:.1} {}", val, name);
        }
    }
    format!("{:.1}   B", size as f64)
}

fn format_size_decimal(size: u64) -> String {
    const UNITS: &[(&str, u64)] = &[
        ("TB", 1_000_000_000_000),
        ("GB", 1_000_000_000),
        ("MB", 1_000_000),
        ("kB", 1_000),
    ];

    for (name, bytes) in UNITS {
        if size >= *bytes {
            let val = size as f64 / *bytes as f64;
            return format!("{:.1}  {}", val, name);
        }
    }
    format!("{:.1}  B", size as f64)
}

fn format_time(timestamp: i64) -> String {
    const MONTHS: &[&str] = &["Jan", "Feb", "Mar", "Apr", "May", "Jun",
                               "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    #[repr(C)]
    struct Tm {
        tm_sec: i32, tm_min: i32, tm_hour: i32, tm_mday: i32,
        tm_mon: i32, tm_year: i32, tm_wday: i32, tm_yday: i32,
        tm_isdst: i32, tm_gmtoff: i64, tm_zone: *const u8,
    }

    extern "C" {
        fn localtime_r(timep: *const i64, result: *mut Tm) -> *mut Tm;
    }

    unsafe {
        let mut tm: Tm = std::mem::zeroed();
        if localtime_r(&timestamp, &mut tm).is_null() {
            return String::new();
        }

        let year = tm.tm_year + 1900;
        let month = MONTHS[tm.tm_mon as usize % 12];
        let day = tm.tm_mday;
        let hour = tm.tm_hour;
        let min = tm.tm_min;
        let (h12, ampm) = if hour == 0 {
            (12, "am")
        } else if hour < 12 {
            (hour, "am")
        } else if hour == 12 {
            (12, "pm")
        } else {
            (hour - 12, "pm")
        };

        format!("{}-{}-{:02} {:02}:{:02}{}", year, month, day, h12, min, ampm)
    }
}

fn colorize_detail_field(node: &Node, field: &DetailField, value: &str, opts: &DisplayOptions, current_uid: u32) -> String {
    match field {
        DetailField::Typ => {
            let color = match &node.kind {
                NodeKind::Dir => Some("34"),
                NodeKind::File => Some("2"),
                _ => None,
            };
            if let Some(c) = color {
                format!("\x1b[{}m{}\x1b[0m", c, value)
            } else {
                value.to_string()
            }
        },
        DetailField::Perm => colorize_permissions(node.permissions_mode()),
        DetailField::User => {
            if node.uid() == current_uid {
                format!("\x1b[1;34m{}\x1b[0m", value)
            } else {
                format!("\x1b[2m{}\x1b[0m", value)
            }
        },
        DetailField::Group => format!("\x1b[2m{}\x1b[0m", value),
        DetailField::Size => colorize_size(node, value),
        DetailField::Mtime | DetailField::Atime | DetailField::Ctime | DetailField::Btime => {
            colorize_time(value)
        },
        _ => value.to_string(),
    }
}

fn colorize_permissions(mode: u32) -> String {
    let chars = format_permissions(mode);
    let mut result = String::new();

    for (i, ch) in chars.chars().enumerate() {
        if ch == ' ' {
            result.push(' ');
            continue;
        }

        let color = match ch {
            'r' => "33",
            'w' => "31",
            'x' => "32",
            's' | 'S' => "35",
            't' | 'T' => "35",
            '-' => "2",
            _ => "",
        };

        if color.is_empty() {
            result.push(ch);
        } else {
            result.push_str(&format!("\x1b[{}m{}\x1b[0m", color, ch));
        }
    }

    result
}

fn colorize_size(node: &Node, value: &str) -> String {
    if node.is_dir() || value.trim().is_empty() {
        return value.to_string();
    }

    let v = value.trim();
    if let Some(space_pos) = v.rfind(' ') {
        let num_part = &v[..space_pos];
        let unit_part = &v[space_pos+1..];
        let leading_spaces = value.len() - v.len();
        let leading = " ".repeat(leading_spaces);
        return format!("{}\x1b[1m{}\x1b[0m \x1b[2m{}\x1b[0m", 
            leading, num_part.trim(), unit_part);
    }

    value.to_string()
}

fn colorize_time(value: &str) -> String {
    if let Some(space_pos) = value.find(' ') {
        let date_part = &value[..space_pos];
        let time_part = &value[space_pos..];
        format!("\x1b[1;33m{}\x1b[0m{}", date_part, time_part)
    } else {
        value.to_string()
    }
}

pub fn get_username(uid: u32) -> String {
    use std::ffi::CStr;

    extern "C" {
        fn getpwuid(uid: u32) -> *const u8;
    }

    unsafe {
        let pw = getpwuid(uid);
        if pw.is_null() { return uid.to_string(); }
        // pw_name is the first field
        let name_ptr = pw as *const *const i8;
        let name = *name_ptr;
        if name.is_null() { return uid.to_string(); }
        CStr::from_ptr(name).to_string_lossy().to_string()
    }
}

pub fn get_groupname(gid: u32) -> String {
    use std::ffi::CStr;

    extern "C" {
        fn getgrgid(gid: u32) -> *const u8;
    }

    unsafe {
        let gr = getgrgid(gid);
        if gr.is_null() { return gid.to_string(); }
        let name_ptr = gr as *const *const i8;
        let name = *name_ptr;
        if name.is_null() { return gid.to_string(); }
        CStr::from_ptr(name).to_string_lossy().to_string()
    }
}

fn get_current_uid() -> u32 {
    extern "C" {
        fn getuid() -> u32;
    }
    unsafe { getuid() }
}
RUSTEOF

