# Let me check if btime (birth time) is available on this system:
cat > /tmp/test_btime.rs << 'EOF'
use std::os::linux::fs::MetadataExt;

fn main() {
    let meta = std::fs::metadata("/workspace/README.md").unwrap();
    // On Linux, there's st_birthtime if the filesystem supports it
    // libc provides stat64 which might have birthtime
    println!("ctime: {}", meta.st_ctime());
    // We need to use statx syscall for birth time
    use std::os::raw::c_int;

    extern "C" {
        fn statx(dirfd: c_int, pathname: *const i8, flags: c_int, mask: u32, statxbuf: *mut StatxBuf) -> c_int;
    }

    const AT_FDCWD: c_int = -100;
    const AT_EMPTY_PATH: c_int = 0x1000;
    const STATX_BTIME: u32 = 0x800;
    const STATX_ALL: u32 = 0xFFF;

    #[repr(C)]
    struct StatxTimestamp {
        tv_sec: i64,
        tv_nsec: u32,
        _pad: i32,
    }

    #[repr(C)]
    struct StatxBuf {
        stx_mask: u32,
        stx_blksize: u32,
        stx_attributes: u64,
        stx_nlink: u32,
        stx_uid: u32,
        stx_gid: u32,
        stx_mode: u16,
        _pad1: [u16; 1],
        stx_ino: u64,
        stx_size: u64,
        stx_blocks: u64,
        stx_attributes_mask: u64,
        stx_atime: StatxTimestamp,
        stx_btime: StatxTimestamp,
        stx_ctime: StatxTimestamp,
        stx_mtime: StatxTimestamp,
        stx_rdev_major: u32, stx_rdev_minor: u32,
        stx_dev_major: u32, stx_dev_minor: u32,
        _pad2: [u64; 14],
    }

    let path = std::ffi::CString::new("/workspace/README.md").unwrap();

    unsafe {
        let mut buf: StatxBuf = std::mem::zeroed();
        let ret = statx(AT_FDCWD, path.as_ptr() as *const i8, 0, STATX_ALL, &mut buf);
        if ret == 0 {
            println!("statx btime: {}", buf.stx_btime.tv_sec);
            println!("statx ctime: {}", buf.stx_ctime.tv_sec);
        } else {
            println!("statx failed");
        }
    }
}
EOF
