fn get_birth_time(path: &std::path::Path) -> Option<i64> {
    use std::ffi::CString;
    use std::os::raw::c_int;

    extern "C" {
        fn statx(dirfd: c_int, pathname: *const i8, flags: c_int, mask: u32, statxbuf: *mut StatxBuf) -> c_int;
    }

    const AT_FDCWD: c_int = -100;
    const STATX_BTIME: u32 = 0x800;

    #[repr(C)]
    struct StatxTimestamp {
        tv_sec: i64,
        tv_nsec: u32,
        _pad: i32,
    }

    #[repr(C)]
    struct StatxBuf {
        stx_mask: u32,
        stx_blksize: u32,
        stx_attributes: u64,
        stx_nlink: u32,
        stx_uid: u32,
        stx_gid: u32,
        stx_mode: u16,
        _pad1: [u16; 1],
        stx_ino: u64,
        stx_size: u64,
        stx_blocks: u64,
        stx_attributes_mask: u64,
        stx_atime: StatxTimestamp,
        stx_btime: StatxTimestamp,
        stx_ctime: StatxTimestamp,
        stx_mtime: StatxTimestamp,
        stx_rdev_major: u32, stx_rdev_minor: u32,
        stx_dev_major: u32, stx_dev_minor: u32,
        _pad2: [u64; 14],
    }

    let path_str = path.to_string_lossy();
    let c_path = CString::new(path_str.as_ref()).ok()?;

    unsafe {
        let mut buf: StatxBuf = std::mem::zeroed();
        let ret = statx(AT_FDCWD, c_path.as_ptr() as *const i8, 0, STATX_BTIME, &mut buf);
        if ret == 0 && buf.stx_mask & STATX_BTIME != 0 {
            Some(buf.stx_btime.tv_sec)
        } else {
            // Fallback to ctime if statx doesn't support btime
            use std::os::unix::fs::MetadataExt;
            std::fs::symlink_metadata(path).ok().map(|m| m.ctime())
        }
    }
}
