cat > /tmp/test_mtime.rs << 'EOF'
use std::os::linux::fs::MetadataExt;

fn main() {
    let paths = [
        "/tmp/test_dir/bigfile.bin",
        "/tmp/test_dir/file1.txt", 
        "/tmp/test_dir/.hidden_dir",
        "/tmp/test_dir/symlink1",
    ];
    for p in &paths {
        if let Ok(m) = std::fs::symlink_metadata(p) {
            println!("{}: mtime={}, mtime_ns={}", p, m.st_mtime(), m.st_mtime_nsec());
        }
    }
}
EOF
